// t = beskärningsmetoder (cut, thin, ground, hedge, remove), se guiden i appen.
// z = odlingszon (konservativ, varierar med sort och läge), ht = ungefärlig höjd fullvuxen, jm = jordmån och läge.
// sun = ljus (s sol, h halvskugga, k skugga), wat = vatten (d torktålig, m normalt, w vattenkrävande), bt = blomningstid (månader).
